package vn.edu.eaut.lab7.controller;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;
@WebServlet("/login")public class LoginServlet extends HttpServlet{protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException,ServletException{String u=q.getParameter("username"),pw=q.getParameter("password");if(("admin".equals(u)||"user".equals(u))&&"123456".equals(pw)){HttpSession s=q.getSession();s.setAttribute("username",u);s.setAttribute("role","admin".equals(u)?"ADMIN":"USER");p.sendRedirect(q.getContextPath()+"/admin/dashboard");}else{q.setAttribute("error","Sai tài khoản hoặc mật khẩu");q.getRequestDispatcher("/login.jsp").forward(q,p);}}}
